package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.FavoriteDao;import org.nonfood.oilplants.dao.PlantDao;import org.nonfood.oilplants.model.User;import java.io.*;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;
@WebServlet("/plant") public class PlantDetailServlet extends HttpServlet{private static final java.util.logging.Logger LOG=java.util.logging.Logger.getLogger(PlantDetailServlet.class.getName());protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{long id=Long.parseLong(r.getParameter("id"));var plant=new PlantDao().findById(id,false);if(plant.isEmpty()){s.sendError(404);return;}r.setAttribute("plant",plant.get());User u=WebSupport.user(r);if(u!=null)r.setAttribute("isFavorite",new FavoriteDao().contains(u.getId(),id));try{new org.nonfood.oilplants.dao.UserDiscoveryDao().recordPlantView(id,u==null?null:u.getId());}catch(Exception historyError){LOG.log(java.util.logging.Level.WARNING,"Could not update aggregate plant views",historyError);}String scientific=plant.get().getScientificName();if(scientific!=null&&!scientific.isBlank()){String q=URLEncoder.encode(scientific,StandardCharsets.UTF_8);r.setAttribute("powoUrl","https://powo.science.kew.org/results?q="+q);r.setAttribute("gbifUrl","https://www.gbif.org/species/search?q="+q);}WebSupport.view(r,s,"plants/detail");}catch(NumberFormatException e){s.sendError(404);}catch(Exception e){WebSupport.error(r,s,e,"植物详情暂时不可用。");}}}
